import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"实战流水线","description":"","frontmatter":{},"headers":[],"relativePath":"pipelines/index.md","filePath":"pipelines/index.md","lastUpdated":1787714366000}'),n={name:"pipelines/index.md"};function s(d,t,i,l,h,p){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="实战流水线" tabindex="-1">实战流水线 <a class="header-anchor" href="#实战流水线" aria-label="Permalink to &quot;实战流水线&quot;">​</a></h1><p>方法论讲<strong>该怎么做</strong>，Prompt 库讲<strong>那一句怎么写</strong>，工具地图讲<strong>用什么</strong>。这个板块讲的是把它们串起来之后，<strong>一条具体的链路实际怎么跑</strong>。</p><h2 id="和其他板块的区别" tabindex="-1">和其他板块的区别 <a class="header-anchor" href="#和其他板块的区别" aria-label="Permalink to &quot;和其他板块的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>板块</th><th>回答</th><th>是否绑定具体工具</th></tr></thead><tbody><tr><td><a href="/method/">创意方法论</a></td><td>该怎么推进</td><td>否，工具无关</td></tr><tr><td><a href="/tools/">工具地图</a></td><td>用哪个工具</td><td>是，但只讲定位</td></tr><tr><td><strong>实战流水线</strong></td><td><strong>这套工具组合起来怎么跑</strong></td><td><strong>是，绑得很死</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">这个板块的内容保质期最短</p><p>流水线绑定具体工具的具体形态。工具改版，整篇可能就得重写。</p><p><strong>这是有意的取舍</strong>——换来的是可操作性。方法论页面写得再稳，也回答不了&quot;我下载的文件该怎么归档&quot;。</p></div><h2 id="本板块内容" tabindex="-1">本板块内容 <a class="header-anchor" href="#本板块内容" aria-label="Permalink to &quot;本板块内容&quot;">​</a></h2><table tabindex="0"><thead><tr><th>流水线</th><th>组合</th><th>适合</th></tr></thead><tbody><tr><td><a href="/pipelines/codex-gemini">Codex + Gemini Flow</a></td><td>Codex 客户端做本地编排，Flow 做生成</td><td>镜头多、要反复改版的短视频</td></tr></tbody></table><h2 id="什么样的内容适合写成流水线" tabindex="-1">什么样的内容适合写成流水线 <a class="header-anchor" href="#什么样的内容适合写成流水线" aria-label="Permalink to &quot;什么样的内容适合写成流水线&quot;">​</a></h2><p>三个特征，缺一个就不必单开一篇：</p><ol><li><strong>跨工具</strong>。单个工具的用法归 <a href="/prompts/">Prompt 库</a> 或 <a href="/tools/reviews">工具评测</a>。</li><li><strong>有交接问题</strong>。两个系统之间靠人搬运，就一定有命名、归档、版本的规矩要定。</li><li><strong>重复跑得起来</strong>。只做一次的链路不值得沉淀——<strong>建流水线本身是有成本的，要在第二个项目才回本。</strong></li></ol><h2 id="写自己的流水线" tabindex="-1">写自己的流水线 <a class="header-anchor" href="#写自己的流水线" aria-label="Permalink to &quot;写自己的流水线&quot;">​</a></h2><p>暂时没有专用模板，<a href="/templates/case-study">案例拆解模板</a> 的结构基本够用。重点记三件事：</p><ul><li><strong>交接界面长什么样</strong>（目录结构、命名规范）——这是流水线的命脉</li><li><strong>哪一步没能自动化，为什么</strong>——比能自动化的部分更有价值</li><li><strong>搭建成本</strong>（第一次花了多久）——决定别人要不要跟</li></ul>',13)])])}const m=a(n,[["render",s]]);export{c as __pageData,m as default};
